import {canonicalUrl} from './routing.js';
import {treatmentBalances} from './home-balances.js';
import {sessionsFor,appendCourseSession} from './courses.js';
const APP_VERSION='3.1.0';
const $ = (q, root=document) => root.querySelector(q);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => localDate(new Date());
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const money = v => new Intl.NumberFormat('es-PY',{style:'currency',currency:'PYG',maximumFractionDigits:0}).format(v||0);
const date = s => s ? new Date(s.length===10?s+'T12:00:00':s).toLocaleDateString('es-PY',{day:'2-digit',month:'short',year:'numeric'}) : '—';
const uid = () => crypto.randomUUID();
const colors={Sano:'#8596a7',Caries:'#f87171','Obturación (Resina)':'#60a5fa',Endodoncia:'#b794f4',Corona:'#d4af37',Ausente:'#374151'};
const faces=['Vestibular','Lingual','Mesial','Distal','Oclusal'];
const emptyDB=()=>({patients:[],appointments:[],sessions:[],treatments:[],payments:[],teeth:{}});
let db, auth, view='dashboard', selected=null, tab='info', dentition='adult', installPrompt;
let revision=0, csrf='', needsSetup=false;
async function api(action,body){
 let response;
 try { response=await fetch(`./api/index.php?action=${action}`,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)}); }
 catch {throw Error('Sin conexión con el servidor. No se guardaron los cambios.');}
 let result;
 try {result=await response.json();} catch {throw Error('El servidor no respondió como API. Revisá PHP y la configuración del hosting.');}
 if(!response.ok){if(response.status===401&&auth){auth=false;db=emptyDB();$('#modal').close();render();}const error=Error(result.error||'No se pudo completar la operación.');error.status=response.status;error.code=result.code;error.diagnostic=result.diagnostic;throw error;}
 return result;
}
async function loadClinic(){const result=await api('clinic');validateBackup({format:'vital-dent',version:1,data:result.data});db=result.data;revision=result.revision;}
async function commit(next){validateBackup({format:'vital-dent',version:1,data:next});const result=await api('clinic',{revision,data:next});revision=result.revision;db=result.data;}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function patient(id){return db.patients.find(p=>p.id===id);}
function pname(id){return patient(id)?.name || 'Paciente no disponible';}
function button(label,action,extra='',cls=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function field(label,name,type='text',value='',required=false,extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`;}
function area(label,name,value=''){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;}
function selectField(label,name,options,value=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;}
function patientSelect(value=''){return selectField('Paciente','patientId',db.patients.filter(p=>p.active || p.id===value).map(p=>[p.id,p.name]),value);}
function table(head,rows,empty='No hay registros todavía.'){return rows.length?`<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:`<div class="empty">${empty}</div>`;}
function person(p){return `<div class="person"><span class="avatar">${esc(p.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><strong>${esc(p.name)}</strong><small>C.I. ${esc(p.document||'Sin registrar')}</small></div></div>`;}
function brand(){return `<button type="button" class="brand" data-nav="dashboard" aria-label="Vital Dent · Inicio"><img src="./icons/icon.svg" width="38" height="38" alt=""><span>Vital <span>Dent</span></span></button>`;}
function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1>${sub?`<div class="muted">${sub}</div>`:''}</div><div class="actions">${actions}</div></div>`;}
function busy(button,label){const html=button.innerHTML;button.disabled=true;button.setAttribute('aria-busy','true');button.innerHTML=`<span class="spinner" aria-hidden="true"></span>${label}`;return ()=>{button.innerHTML=html;button.disabled=false;button.removeAttribute('aria-busy');};}
function budget(pid){return db.treatments.filter(t=>!pid||t.patientId===pid).reduce((s,t)=>s+t.cost,0);}
function paid(pid){return db.payments.filter(t=>!pid||t.patientId===pid).reduce((s,t)=>s+t.amount,0);}
function stats(items){return `<div class="grid stats">${items.map(([label,val,foot,icon])=>`<div class="card"><span class="stat-icon">${icon}</span><div class="muted">${label}</div><div class="stat-value">${val}</div>${label==='Ingresos de la semana'?'<small class="muted">Desde el lunes hasta hoy</small>':''}</div>`).join('')}</div>`;}
function render(){
 if(!auth){$('#modal').replaceChildren();login();return;}
 const pages={dashboard:dashboard,patients:patients,agenda:agenda,finance:finance,settings:settings,patient:patientPage,course:coursePage};
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<nav class="nav" aria-label="Principal">${[['dashboard','◈','Inicio'],['patients','♧','Pacientes'],['agenda','▦','Agenda']].map(([v,i,l])=>`<button class="${view===v||['patient','course'].includes(view)&&v==='patients'?'active':''}" data-nav="${v}" ${view===v||['patient','course'].includes(view)&&v==='patients'?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${i}</span>${l}</button>`).join('')}<details class="nav-more" ${['finance','settings'].includes(view)?'open':''}><summary>Más</summary><div><button type="button" data-nav="finance">Pagos</button><button type="button" data-nav="settings">Ajustes</button></div></details></nav></aside><main class="main"><header class="topbar"><span>${new Date().toLocaleDateString('es-PY',{weekday:'long',day:'numeric',month:'long'})}</span><div class="actions"><span id="online" class="badge ${navigator.onLine?'green':''}">${navigator.onLine?'● En línea':'● Sin conexión'}</span><span class="doctor">Dra. Karen Frutos</span>${button('Actualizar datos','refresh','','small')}${button('Salir','logout','','small')}</div></header><div class="content">${pages[view]() }</div></main></div>`;
}
let homeQuery='',homeFilter='all',homeLimit=15,homeCitas='next';
function dashboard(){return head('Mi consultorio','',button('+ Agendar cita','appointment-form')+button('+ Anotar atención','attention-form','','primary'))+`<div class="home-layout"><section class="home-notes" aria-labelledby="home-title"><div class="home-section-head"><h2 id="home-title">Atenciones y tratamientos</h2><span class="muted">Fecha, tratamiento y pagos</span></div><div class="home-filters"><div class="home-search"><label class="sr-only" for="home-search">Buscar paciente o tratamiento</label><input id="home-search" type="search" placeholder="Buscar paciente o tratamiento" value="${esc(homeQuery)}"></div><div><label class="sr-only" for="home-filter">Mostrar tratamientos</label><select id="home-filter"><option value="all" ${homeFilter==='all'?'selected':''}>Todos</option><option value="done" ${homeFilter==='done'?'selected':''}>Realizados</option><option value="pending" ${homeFilter==='pending'?'selected':''}>Por hacer</option></select></div></div><div id="home-records">${homeRecords()}</div><details class="home-help"><summary>¿Cómo se aplican los pagos?</summary><p>El pago de una atención se aplica a ese tratamiento. Los pagos anteriores sin un tratamiento elegido se aplican primero a los importes más antiguos. Lo que sobra queda a favor del paciente. Las fechas que no se habían anotado aparecen como «Sin fecha».</p></details></section><aside class="home-appointments card" aria-labelledby="home-citas-title"><div class="home-section-head"><h2 id="home-citas-title">Citas</h2><span class="calendar-mark" aria-hidden="true">▦</span></div><div class="home-switch" aria-label="Ver citas"><button type="button" data-action="home-citas" data-value="next" aria-pressed="${homeCitas==='next'}">Próximas</button><button type="button" data-action="home-citas" data-value="done" aria-pressed="${homeCitas==='done'}">Ya atendidos</button></div>${homeAppointments()}<button type="button" class="btn home-agenda-link" data-nav="agenda">Ver calendario</button></aside></div>`;}
function homeRecords(){
 const accounts=treatmentBalances(db);const q=homeQuery.trim().toLocaleLowerCase();
 const list=db.treatments.map((t,index)=>({t,index})).filter(({t})=>(homeFilter==='all'||(t.status==='Completado')===(homeFilter==='done'))&&(!q||[pname(t.patientId),patient(t.patientId)?.document,t.description].some(v=>String(v||'').toLocaleLowerCase().includes(q)))).sort((a,b)=>(b.t.date||'').localeCompare(a.t.date||'')||b.index-a.index);
 if(!list.length)return `<div class="home-empty"><span aria-hidden="true">✧</span><h3>${q?'No encontramos ese paciente o tratamiento.':db.treatments.length?'No hay tratamientos en esta vista.':'Tu primera atención empieza aquí.'}</h3><p>${db.treatments.length?'Probá otra búsqueda o elegí «Todos».':'Usá «Anotar atención» para guardar lo realizado y lo que pagó el paciente.'}</p></div>`;
 return `<div class="attention-list">${list.slice(0,homeLimit).map(({t})=>treatmentCard(t,accounts)).join('')}</div>${list.length>homeLimit?button('Ver más atenciones','home-more','','home-load-more'):''}`;
}
function treatmentCard(t,accounts,includeStatus=false){
 const visits=sessionsFor(db,t.id);const multi=Boolean(t.longTerm)||visits.length>1;

 const account=accounts.rows.get(t.id);const credit=accounts.credit.get(t.patientId)||0;
 return `<article class="attention-card" data-treatment-card="${t.id}"><div class="attention-top"><button type="button" class="patient-link" data-action="open-patient" data-id="${t.patientId}"><span class="attention-initial" aria-hidden="true">${esc(pname(t.patientId).slice(0,1))}</span>${esc(pname(t.patientId))}</button><span class="attention-date">${t.date?date(t.date):'Sin fecha'}</span><details class="record-options"><summary aria-label="Opciones de ${esc(t.description)}">•••</summary><div>${button('Ver pagos','payment-history',`data-id="${t.patientId}" data-treatment="${t.id}"`,'small')}${multi?editButton('treatments',t.id):button('Editar','attention-form',`data-id="${t.id}"`,'small')}${deleteButton('treatments',t.id)}</div></details></div><div class="attention-description"><h3>${esc(t.description)}</h3>${t.status!=='Completado'?`<span class="badge">${t.status==='En Curso'?'En curso':'Por hacer'}</span>`:''}</div><div class="course-card-link">${button(`${visits.length} ${visits.length===1?'sesión':'sesiones'} · Ver seguimiento`,'open-course',`data-id="${t.id}"`,'small')}</div><div class="attention-bottom"><dl class="attention-money"><div><dt>Total</dt><dd>${money(t.cost)}</dd></div><div><dt>Pagó</dt><dd class="amount-paid">${money(account.paid)}</dd></div><div><dt>Falta</dt><dd class="${account.balance?'amount-due':'amount-settled'}">${account.balance?money(account.balance):'Al día'}</dd></div></dl><div class="attention-actions">${multi?(t.status!=='Completado'?button('Nueva sesión','course-session',`data-id="${t.id}"`,'small primary')+(account.balance?button('+ Pago','payment-form',`data-id="${t.patientId}" data-treatment="${t.id}"`,'small'):''):button('Ver seguimiento','open-course',`data-id="${t.id}"`,'small')):t.status!=='Completado'?button('Anotar atención','attention-form',`data-id="${t.id}"`,'small primary'):account.balance?button('+ Pago','payment-form',`data-id="${t.patientId}" data-treatment="${t.id}"`,'small primary'):button('Ver pagos','payment-history',`data-id="${t.patientId}" data-treatment="${t.id}"`,'small')}</div></div>${credit?`<div class="patient-credit">${money(credit)} a favor del paciente</div>`:''}${includeStatus?`<div class="treatment-state"><label for="state-${t.id}">Estado</label><select id="state-${t.id}" data-treatment="${t.id}">${['Pendiente','En Curso','Completado'].map(v=>`<option value="${v}" ${v===t.status?'selected':''}>${v}</option>`).join('')}</select></div>`:''}</article>`;
}
function homeAppointments(){
 let entries;
 if(homeCitas==='next')entries=db.appointments.filter(a=>a.date>=today()&&!['Atendida','Cancelada'].includes(a.status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(a=>({...a,kind:'appointment'}));
 else{
 const sessionAppointments=new Set(db.sessions.map(s=>s.appointmentId).filter(Boolean));
 entries=[...db.sessions.map(s=>({...s,reason:s.procedure,kind:'session',time:''})),...db.appointments.filter(a=>a.status==='Atendida'&&!sessionAppointments.has(a.id)).map(a=>({...a,kind:'appointment'}))].sort((a,b)=>(b.date+(b.time||'')).localeCompare(a.date+(a.time||'')));
 }
 if(!entries.length)return `<p class="home-citas-empty">${homeCitas==='next'?'No hay próximas citas agendadas.':'Todavía no hay atenciones registradas.'}</p>`;
 return `<ul class="home-cita-list">${entries.slice(0,6).map(a=>`<li><div class="cita-when"><strong>${a.date===today()?'Hoy':date(a.date)}</strong>${a.time?`<span>${esc(a.time)}</span>`:''}</div><div class="cita-person"><strong>${esc(pname(a.patientId))}</strong><span>${esc(a.reason)}</span></div>${homeCitas==='next'&&a.date===today()?button('Atender','attention-form',`data-appointment="${a.id}"`,'small'):button('Ver ficha','open-patient',`data-id="${a.patientId}"`,'small')}</li>`).join('')}</ul>`;
}
function attentionForm(treatmentId,appointmentId){
 const appointment=db.appointments.find(a=>a.id===appointmentId);
 const treatment=db.treatments.find(t=>t.id===(treatmentId||appointment?.treatmentId));
 if(treatment?.longTerm||treatment&&sessionsFor(db,treatment.id).length>1){courseSessionForm(treatment.id,appointmentId);return;}
 if(!treatment&&!appointment&&!requirePatients())return;
 const patientId=treatment?.patientId||appointment?.patientId||'';
 const editing=treatment?.status==='Completado';const targetId=treatment?.id||uid();const paymentId=uid();
 const fixed=patientId?`<div class="field"><label>Paciente</label><strong>${esc(pname(patientId))}</strong><input type="hidden" name="patientId" value="${patientId}"></div>`:patientSelect();
 modal(editing?'Editar atención':'Anotar atención',`<div id="attention-alert"></div><div class="form-grid">${fixed}${field('Fecha','date','date',treatment?.date||today(),true,`max="${today()}"`)}<div class="full">${field('¿Qué se realizó?','description','text',treatment?.description||appointment?.reason||'',true,'maxlength="500"')}</div>${field('Total del tratamiento (Gs.)','cost','number',treatment?.cost??'',true,'min="0" max="1000000000" step="1"')}${!editing?field('Pagó ahora (Gs.)','amount','number',0,true,'min="0" max="1000000000" step="1"'):''}</div>${!editing?`<div id="attention-method" hidden>${selectField('Cómo pagó','method',['Efectivo','Transferencia','Tarjeta'])}</div>`:''}<div id="attention-preview" class="attention-preview" aria-live="polite"></div>`,async f=>{
 const next=structuredClone(db);const pid=f.get('patientId');const description=f.get('description').trim();
 if(!description)throw Error('Escribí qué tratamiento se realizó.');
 const record={...treatment,id:targetId,patientId:pid,description,cost:Number(f.get('cost')),date:f.get('date'),phase:treatment?.phase||'Fase I',tooth:treatment?.tooth||'',status:'Completado'};
 if(appointment)record.appointmentId=appointment.id;
 if(treatment)next.treatments[next.treatments.findIndex(t=>t.id===targetId)]=record;else next.treatments.push(record);
 if(!editing&&Number(f.get('amount'))>0)next.payments.push({id:paymentId,patientId:pid,treatmentId:targetId,date:record.date,description,amount:Number(f.get('amount')),method:f.get('method')});
 const session=next.sessions.find(s=>s.treatmentId===targetId);
 if(session&&sessionsFor(next,targetId).length===1){session.date=record.date;if(!treatment||session.procedure===treatment.description)session.procedure=description;}
 else if(!editing)next.sessions.push({id:uid(),patientId:pid,treatmentId:targetId,...(appointment?{appointmentId:appointment.id}:{}),date:record.date,procedure:description,notes:'',anesthesia:'',materials:'',url:'',files:[]});
 if(appointment)next.appointments.find(a=>a.id===appointment.id).status='Atendida';
 await commit(next);
 });
 const form=$('#modal-form');const preview=()=>{
 const values=new FormData(form);const pid=values.get('patientId');const cost=Number(values.get('cost'));const amount=editing?0:Number(values.get('amount'));
 const next=structuredClone(db);const t={...treatment,id:targetId,patientId:pid,cost:Number.isFinite(cost)&&cost>=0?cost:0,date:values.get('date')};
 if(treatment)next.treatments[next.treatments.findIndex(x=>x.id===targetId)]=t;else next.treatments.push(t);
 if(amount>0&&Number.isFinite(amount))next.payments.push({patientId:pid,treatmentId:targetId,amount});
 const model=treatmentBalances(next);const row=model.rows.get(targetId);const credit=model.credit.get(pid)||0;
 $('#attention-preview').innerHTML=`<span>Queda por pagar</span><strong>${money(row.balance)}</strong>${credit?`<small>${money(credit)} queda a favor del paciente.</small>`:''}`;
 const warning=patient(pid)?.alert;$('#attention-alert').innerHTML=warning?`<div class="alert" role="alert"><strong>Alerta médica</strong><br>${esc(warning)}</div>`:'';const method=$('#attention-method');if(method)method.hidden=!(amount>0);
 };form.addEventListener('input',preview);form.addEventListener('change',preview);preview();
}
function paymentHistory(id,treatmentId){
 const treatment=db.treatments.find(t=>t.id===treatmentId&&t.patientId===id);
 const payments=db.payments.filter(p=>p.patientId===id&&(!treatment||p.treatmentId===treatment.id)).sort((a,b)=>b.date.localeCompare(a.date));
 const applied=treatment?treatmentBalances(db).rows.get(treatment.id).paid:0;const general=treatment?Math.max(0,applied-Math.min(treatment.cost,payments.reduce((n,p)=>n+p.amount,0))):0;
 const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>Pagos de ${esc(treatment?.description||pname(id))}</h2>${button('✕','close','aria-label="Cerrar"','small')}</div>${general?`<p class="patient-credit">${money(general)} aplicados desde el saldo general del paciente. ${button('Ver pagos del paciente','payment-history',`data-id="${id}"`,'small')}</p>`:''}${payments.length?`<ul class="simple-payments">${payments.map(p=>`<li><div><strong>${money(p.amount)}</strong><span>${date(p.date)} · ${esc(p.method)}</span><small>${esc(p.description)}</small></div><div class="actions">${editButton('payments',p.id)}${deleteButton('payments',p.id)}</div></li>`).join('')}</ul>`:'<p class="muted">Todavía no hay pagos anotados para esta vista.</p>'}`;d.oncancel=null;d.showModal();
}

let courseId=null,courseTab='sessions',courseLimit=12,sessionFilter='';
function treatmentSelect(pid,value='',name='treatmentId',label='Tratamiento (opcional)'){
 return selectField(label,name,[['','Sin tratamiento específico'],...db.treatments.filter(t=>t.patientId===pid).map(t=>[t.id,t.description])],value);
}
function bindTreatmentPatient(){
 const patientInput=$('#f-patientId'),target=$('#f-treatmentId');if(!patientInput||!target)return;
 patientInput.addEventListener('change',()=>{target.innerHTML='<option value="">Sin tratamiento específico</option>'+db.treatments.filter(t=>t.patientId===patientInput.value).map(t=>`<option value="${t.id}">${esc(t.description)}</option>`).join('');});
}
function visitArticle(s,number=null){
 const treatment=db.treatments.find(t=>t.id===s.treatmentId);
 return `<article class="visit-note" data-session-id="${s.id}"><div class="visit-heading"><div>${number!==null?`<span class="visit-number">Sesión ${number}</span>`:''}<span class="muted">${date(s.date)}</span></div>${editButton('sessions',s.id)}</div><h3>${esc(s.procedure)}</h3>${s.stage?`<span class="badge">${esc(s.stage)}</span>`:''}${s.notes?`<p class="clinical-text">${esc(s.notes)}</p>`:''}${s.anesthesia||s.materials?`<p class="muted">${s.anesthesia?`Anestesia: ${esc(s.anesthesia)}`:''}${s.anesthesia&&s.materials?' · ':''}${s.materials?`Materiales: ${esc(s.materials)}`:''}</p>`:''}${view!=='course'?`<div class="visit-treatment">${treatment?button(esc(treatment.description),'open-course',`data-id="${treatment.id}"`,'small'):'Sin tratamiento asignado'}</div>`:''}<div class="actions">${(s.files||[]).map((f,i)=>button(`↗ ${esc(f.name)}`,'attachment',`data-id="${s.id}" data-index="${i}"`,'small')).join('')}${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Ver estudio ↗</a>`:''}</div></article>`;
}
function coursePage(){
 const t=db.treatments.find(t=>t.id===courseId);if(!t){view='patient';tab='plans';return patientPage();}
 const visits=sessionsFor(db,t.id),account=treatmentBalances(db).rows.get(t.id);
 const payments=db.payments.filter(p=>p.treatmentId===t.id&&p.patientId===t.patientId);
 const direct=payments.reduce((n,p)=>n+p.amount,0);const general=Math.max(0,account.paid-Math.min(t.cost,direct));
 const appointments=db.appointments.filter(a=>a.treatmentId===t.id&&a.date>=today()&&!['Atendida','Cancelada'].includes(a.status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
 const label=t.status==='Completado'?'Finalizado':t.status==='En Curso'?'En curso':'Por comenzar';
 let body;
 if(courseTab==='sessions')body=`<section class="card"><div class="home-section-head"><h2>Historial de sesiones</h2><span class="muted">${visits.length} registradas</span></div>${visits.length?visits.map((s,i)=>({s,number:i+1})).reverse().slice(0,courseLimit).map(x=>visitArticle(x.s,x.number)).join(''):'<div class="empty">Todavía no hay sesiones en este tratamiento.</div>'}${visits.length>courseLimit?button('Ver más sesiones','course-more','','home-load-more'):''}</section>`;
 else if(courseTab==='payments')body=`<section class="card"><h2>Pagos de este tratamiento</h2>${general?`<p class="patient-credit">${money(general)} aplicados desde el saldo general del paciente. ${button('Ver pagos del paciente','payment-history',`data-id="${t.patientId}"`,'small')}</p>`:''}${paymentTable(payments)}<p class="footer-note">El excedente queda a favor del paciente y puede aplicarse a sus otros tratamientos.</p></section>`;
 else body=`<section class="card"><div class="home-section-head"><h2>Plan y objetivos</h2>${editButton('treatments',t.id)}</div><p class="clinical-text">${esc(t.plan||'Todavía no se anotó un plan para este tratamiento.')}</p>${t.stage?`<div class="summary-line"><span>Etapa actual</span><strong>${esc(t.stage)}</strong></div>`:''}${t.tooth?`<div class="summary-line"><span>Pieza</span><strong>${esc(t.tooth)}</strong></div>`:''}</section>`;
 return head(esc(t.description),`Paciente: ${esc(pname(t.patientId))}`,button('← Tratamientos del paciente','back-to-patient')+(t.status!=='Completado'?button('Agendar control','appointment-form',`data-treatment="${t.id}"`)+button('+ Nueva sesión','course-session',`data-id="${t.id}"`,'primary'):''))+`${patient(t.patientId)?.alert?`<div class="alert"><strong>Alerta médica</strong><br>${esc(patient(t.patientId).alert)}</div>`:''}<section class="course-overview card"><div class="course-metadata"><span class="badge ${t.status==='Completado'?'green':''}">${label}</span><span>${t.date?`Inicio: ${date(t.date)}`:'Inicio sin fecha'}</span><span>${visits.length} sesiones</span><div class="course-state"><label for="course-state">Estado</label><select id="course-state" data-treatment="${t.id}">${[['Pendiente','Por comenzar'],['En Curso','En curso'],['Completado','Finalizado']].map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="course-budget"><dl class="attention-money"><div><dt>Total acordado</dt><dd>${money(t.cost)}</dd></div><div><dt>Pagó</dt><dd class="amount-paid">${money(account.paid)}</dd></div><div><dt>Falta</dt><dd class="amount-due">${money(account.balance)}</dd></div></dl>${button('+ Anotar pago','payment-form',`data-id="${t.patientId}" data-treatment="${t.id}"`)}</div><p class="footer-note">Cada sesión agrega una nota al historial; el total acordado no se vuelve a sumar.</p></section>${appointments.length?`<div class="course-next">Próximo control: <strong>${date(appointments[0].date)} · ${esc(appointments[0].time)}</strong></div>`:''}<nav class="tabs" aria-label="Seguimiento del tratamiento">${[['sessions','Sesiones'],['payments','Pagos'],['plan','Plan']].map(([key,text])=>`<button type="button" data-action="course-tab" data-value="${key}" class="${courseTab===key?'active':''}">${text}</button>`).join('')}</nav>${body}`;
}
function courseSessionForm(treatmentId,appointmentId){
 const t=db.treatments.find(t=>t.id===treatmentId);if(!t){toast('Tratamiento no disponible.');return;}
 if(t.status==='Completado'){toast('El tratamiento está finalizado. Cambiá su estado a En Curso para continuarlo.');return;}
 const appointment=db.appointments.find(a=>a.id===appointmentId);const sessionId=uid(),paymentId=uid();
 modal(`Nueva sesión · ${esc(t.description)}`,`<p class="muted">${esc(pname(t.patientId))}</p>${patient(t.patientId)?.alert?`<div class="alert"><strong>Alerta médica</strong><br>${esc(patient(t.patientId).alert)}</div>`:''}<div class="form-grid">${field('Fecha de la sesión','date','date',today(),true,`max="${today()}"`)}${field('Etapa actual (opcional)','stage','text',t.stage||'',false,'maxlength="500"')}${field('¿Qué se realizó hoy?','procedure','text','',true,'maxlength="500"')}${field('Pagó en este control (Gs.)','amount','number',0,true,'min="0" max="1000000000" step="1"')}${area('Evolución y notas','notes')}</div><div id="course-payment-method" hidden>${selectField('Cómo pagó','method',['Efectivo','Transferencia','Tarjeta'])}</div><details class="session-extra"><summary>Materiales, anestesia y estudios</summary>${field('Anestesia','anesthesia')}${field('Materiales','materials')}${field('Enlace a estudio (HTTPS)','url','url')}${field('Adjuntar imágenes o PDF (10 MB por sesión)','files','file','',false,'multiple accept="image/png,image/jpeg,image/webp,application/pdf"')}</details>`,async f=>{
 const procedure=f.get('procedure').trim();if(!procedure)throw Error('Anotá qué se realizó en este control.');
 const files=await sessionFiles(f);const url=f.get('url');if(url&&new URL(url).protocol!=='https:')throw Error('El enlace debe utilizar HTTPS.');
 const record={id:sessionId,patientId:t.patientId,date:f.get('date'),procedure,notes:f.get('notes'),stage:f.get('stage'),anesthesia:f.get('anesthesia'),materials:f.get('materials'),url,files};
 const payment=Number(f.get('amount'))>0?{id:paymentId,patientId:t.patientId,date:record.date,amount:Number(f.get('amount')),description:`${t.description} · ${procedure}`,method:f.get('method')}:null;
 await commit(appendCourseSession(db,t.id,record,payment,appointment?.id));
 });
 $('#f-amount').addEventListener('input',()=>$('#course-payment-method').hidden=!(Number($('#f-amount').value)>0));
}
async function sessionFiles(f){
 const files=f.getAll('files').filter(x=>x.size);
 if(files.reduce((n,x)=>n+x.size,0)>10*1024*1024)throw Error('Los adjuntos superan 10 MB.');
 if(files.some(x=>!['image/png','image/jpeg','image/webp','application/pdf'].includes(x.type)))throw Error('Usá PNG, JPEG, WebP o PDF.');
 return Promise.all(files.map(readFile));
}

function patients(){return head('Pacientes','',button('+ Nuevo paciente','patient-form','','primary'))+`<section class="card"><div class="field search"><label for="patient-search">Buscar paciente</label><input id="patient-search" placeholder="Nombre, cédula o teléfono" autocomplete="off"></div><div id="patient-results">${patientRows(db.patients)}</div></section>`;}
function patientRows(list){return '<div class="patients-table">'+table(['Paciente','Teléfono','Estado','Historia clínica'],list.map(p=>`<tr><td>${person(p)}</td><td>${esc(p.phone||'—')}</td><td><span class="badge ${p.active?'green':''}">${p.active?'Activo':'Archivado'}</span></td><td>${button('Abrir ficha →','open-patient',`data-id="${p.id}"`,'small')}</td></tr>`),'Sin pacientes registrados.')+'</div>';}
function patientPage(){const p=patient(selected);if(!p){view='patients';return patients();}return head(esc(p.name),`C.I. ${esc(p.document||'Sin registrar')} · ${esc(p.phone||'Sin teléfono')}`,button('← Pacientes','go-patients')+button('Editar ficha','patient-form',`data-id="${p.id}"`))+`${p.alert?`<div class="alert" role="alert"><strong>⚠ Alerta médica crítica</strong><br>${esc(p.alert)}</div>`:''}<nav class="tabs" aria-label="Historia clínica">${[['info','Datos personales'],['teeth','Odontograma'],['sessions','Evolución clínica'],['plans','Plan de tratamiento']].map(([v,l])=>`<button class="${tab===v?'active':''}" data-tab="${v}">${l}</button>`).join('')}</nav>${({info:()=>`<div class="grid two-col"><section class="card"><h2>Datos del paciente</h2>${[['Nombre',p.name],['Cédula',p.document],['Nacimiento',date(p.birth)],['Teléfono',p.phone],['Correo',p.email],['Dirección',p.address],['Estado',p.active?'Activo':'Archivado']].map(([k,v])=>`<div class="summary-line"><span class="muted">${k}</span><span>${esc(v||'—')}</span></div>`).join('')}</section><section class="card"><h2>Contacto de emergencia</h2><p>${esc(p.emergency||'Sin registrar')}</p><h2>Antecedentes y observaciones</h2><p style="white-space:pre-wrap">${esc(p.notes||'Sin observaciones')}</p></section></div>`,teeth:odontogram,sessions:sessions,plans:plans})[tab]()}`;}
function odontogram(){let upper=dentition==='adult'?[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28]:[55,54,53,52,51,61,62,63,64,65];let lower=dentition==='adult'?[48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38]:[85,84,83,82,81,71,72,73,74,75];return `<section class="card"><div class="page-head"><div><h2>Odontograma FDI / ISO</h2><span class="muted">Seleccioná una pieza para registrar sus caras.</span></div><div class="actions">${button('Permanente','dentition','data-value="adult"',dentition==='adult'?'primary':'')}${button('Temporal','dentition','data-value="child"',dentition==='child'?'primary':'')}</div></div><div class="table-wrap"><div class="arch-label">SUPERIOR · DERECHA DEL PACIENTE → IZQUIERDA</div><div class="tooth-grid ${dentition==='child'?'child':''}">${upper.map(tooth).join('')}</div><div class="arch-label">INFERIOR</div><div class="tooth-grid ${dentition==='child'?'child':''}">${lower.map(tooth).join('')}</div></div><div class="legend">${Object.entries(colors).map(([s,c])=>`<span><i class="dot" style="background:${c}"></i>${s}</span>`).join('')}</div><p class="footer-note">Caras: V vestibular · L lingual/palatina · M mesial · D distal · O oclusal/incisal. El registro conserva el último estado de cada cara.</p></section>`;}
function tooth(n){const t=db.teeth[selected]?.[n]||{};const c=f=>colors[t[f]||'Sano'];return `<button class="tooth" data-action="tooth" data-id="${n}" aria-label="Pieza ${n}. ${faces.map(f=>`${f}: ${t[f]||'Sano'}`).join(', ')}"><span>${n}</span><svg viewBox="0 0 50 50" aria-hidden="true"><g stroke="#111827" stroke-width="2"><path d="M3 3H47L34 16H16Z" fill="${c('Vestibular')}"/><path d="M3 47H47L34 34H16Z" fill="${c('Lingual')}"/><path d="M3 3V47L16 34V16Z" fill="${c([1,4,5,8].includes(Math.floor(n/10))?'Distal':'Mesial')}"/><path d="M47 3V47L34 34V16Z" fill="${c([1,4,5,8].includes(Math.floor(n/10))?'Mesial':'Distal')}"/><path d="M16 16H34V34H16Z" fill="${c('Oclusal')}"/></g></svg></button>`;}
function sessions(){const list=db.sessions.filter(s=>s.patientId===selected);const rows=list.filter(s=>!sessionFilter||(sessionFilter==='unassigned'?!db.treatments.some(t=>t.id===s.treatmentId):s.treatmentId===sessionFilter)).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="card"><div class="page-head"><h2>Sesiones y evolución</h2>${button('+ Registrar sesión','session-form','','primary')}</div>${selectField('Ver sesiones de','sessionFilter',[['','Todos los tratamientos'],['unassigned','Sin tratamiento asignado'],...db.treatments.filter(t=>t.patientId===selected).map(t=>[t.id,t.description])],sessionFilter)}${rows.length?rows.map(s=>visitArticle(s)).join(''):'<div class="empty">Sin sesiones en esta vista.</div>'}</section>`;}

function plans(){const list=db.treatments.filter(t=>t.patientId===selected);const accounts=treatmentBalances(db);return stats([['Total de tratamientos',money(budget(selected)),'','≡'],['Pagó',money(paid(selected)),'','$'],['Falta por pagar',money(Math.max(0,budget(selected)-paid(selected))),'','◷'],['Saldo a favor',money(Math.max(0,paid(selected)-budget(selected))),'','✓']])+`<section><div class="page-head"><h2>Tratamientos del paciente</h2><div class="actions">${button('+ Nuevo tratamiento','treatment-form','','primary')}${button('Registrar abono','payment-form',`data-id="${selected}"`)}</div></div>${list.length?`<div class="attention-list">${list.map(t=>treatmentCard(t,accounts,true)).join('')}</div>`:'<div class="empty">Agregá el primer tratamiento del paciente.</div>'}</section><section class="card" style="margin-top:20px"><h2>Historial de pagos y abonos</h2>${paymentTable(db.payments.filter(p=>p.patientId===selected))}</section>`;}

function appointmentTable(list){return table(['Hora / fecha','Paciente','Motivo','Estado','Acciones'],list.map(a=>`<tr><td><strong>${esc(a.time)}</strong><br><small class="muted">${date(a.date)}</small></td><td>${button(esc(pname(a.patientId)),'open-patient',`data-id="${a.patientId}"`,'small')}</td><td>${esc(a.reason)}</td><td><select aria-label="Estado de cita" data-appointment="${a.id}">${['Programada','Confirmada','Atendida','Cancelada'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select></td><td>${editButton('appointments',a.id)}</td></tr>`));}
let agendaDay=today(),agendaMonth=today().slice(0,7);
function agenda(){
 const [year,month]=agendaMonth.split('-').map(Number);const first=new Date(year,month-1,1);const offset=(first.getDay()+6)%7;const days=new Date(year,month,0).getDate();
 const counts={};for(const a of db.appointments)if(a.status!=='Cancelada')counts[a.date]=(counts[a.date]||0)+1;
 const cells=Array.from({length:offset},()=>'<span aria-hidden="true"></span>');
 for(let day=1;day<=days;day++){const key=agendaMonth+'-'+String(day).padStart(2,'0');const n=counts[key]||0;cells.push(`<button type="button" class="calendar-day ${key===agendaDay?'selected':''} ${key===today()?'today':''}" data-action="calendar-day" data-date="${key}" aria-pressed="${key===agendaDay}" aria-label="${date(key)}, ${n} citas"><strong>${day}</strong>${n?`<span>${n} <span class="calendar-word">${n===1?'cita':'citas'}</span></span>`:''}</button>`);}
 return head('Agenda','',button('+ Agendar cita','appointment-form','','primary'))+`<section class="card"><div class="calendar-toolbar"><div class="actions">${button('‹','calendar-month','data-step="-1" aria-label="Mes anterior"')}<h2>${first.toLocaleDateString('es-PY',{month:'long',year:'numeric'})}</h2>${button('›','calendar-month','data-step="1" aria-label="Mes siguiente"')}</div>${button('Hoy','calendar-today')}</div><div class="calendar-grid calendar-week" aria-hidden="true">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div><p class="muted">Los contadores excluyen citas canceladas.</p></section><section class="card" style="margin-top:20px"><div class="page-head"><h2>${agendaDay?date(agendaDay):'Todas las citas'}</h2><div class="field"><label for="agenda-date">Fecha (vacío: todas)</label><input id="agenda-date" type="date" value="${agendaDay}"></div></div><div id="agenda-results">${appointmentTable(db.appointments.filter(a=>!agendaDay||a.date===agendaDay).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)))}</div></section>`;
}

function finance(){return head('Pagos','',button('+ Registrar cobro','payment-form','','primary'))+stats([['Cobros de hoy',money(db.payments.filter(p=>p.date===today()).reduce((s,p)=>s+p.amount,0)),'Ingresos del día','$'],['Total cobrado',money(paid()),'Histórico registrado','↗'],['Falta por pagar',money(db.patients.reduce((s,p)=>s+Math.max(0,budget(p.id)-paid(p.id)),0)),'Saldo de planes','◷'],['Pacientes con saldo',db.patients.filter(p=>budget(p.id)>paid(p.id)).length,'Seguimiento de pagos','♧']])+`<div class="grid two-col"><section class="card"><h2>Movimientos</h2><div class="field search"><label for="cash-date">Filtrar por fecha (vacío: todas)</label><input type="date" id="cash-date"></div><div id="cash-results">${paymentTable(db.payments)}</div></section><section class="card"><h2>Cuentas por cobrar</h2>${table(['Paciente','Saldo'],db.patients.filter(p=>budget(p.id)>paid(p.id)).map(p=>`<tr><td>${button(esc(p.name),'open-patient',`data-id="${p.id}"`,'small')}</td><td>${money(budget(p.id)-paid(p.id))}</td></tr>`),'No hay saldos pendientes.')}</section></div>`;}
function paymentTable(list){return table(['Fecha','Paciente / concepto','Método','Importe','Acciones'],[...list].sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<tr><td>${date(p.date)}</td><td>${esc(pname(p.patientId))}<br><small class="muted">${esc(p.description)}</small></td><td>${esc(p.method)}</td><td>${money(p.amount)}</td><td>${editButton('payments',p.id)} ${deleteButton('payments',p.id)}</td></tr>`));}
function settings(){return head('Configuración','')+`<div class="grid two-col"><section class="card"><h2>Copias de seguridad</h2><div class="actions">${button('↓ Exportar respaldo JSON','export','','primary')}${button('↑ Restaurar respaldo','import')}</div><p class="footer-note">El respaldo contiene datos clínicos sin cifrar. Guardalo en una ubicación privada. Restaurar reemplaza los registros actuales.</p></section><section class="card"><h2>Acceso de la doctora</h2><p>Usuario: <strong>karen.frutos</strong></p>${button('Cambiar contraseña','password')}</section><section class="card"><h2>Aplicación instalable</h2>${button('Instalar Vital Dent','install')}<p class="footer-note">iPhone: Safari → Compartir → Agregar a pantalla de inicio.</p></section></div>`;}
function modal(title,html,save){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2>${button('✕','close','aria-label="Cerrar"','small')}</div><form id="modal-form">${html}<p class="error" role="alert"></p><div class="actions"><button type="submit" class="btn primary">Guardar</button>${button('Cancelar','close')}</div></form>`;d.showModal();d.oncancel=e=>{if($('#modal-form',d)?.dataset.saving)e.preventDefault();};$('#modal-form').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.saving)return;e.target.dataset.saving='true';const data=new FormData(e.target);const reset=busy(e.submitter,'Guardando…');const closeButtons=[...d.querySelectorAll('[data-action=close]')];closeButtons.forEach(b=>b.disabled=true);try{await save(data);d.close();render();toast('Guardado correctamente');}catch(err){const error=$('.error',d);if(error)error.textContent=err.message||'No se pudo guardar. Intentá nuevamente.';else toast(err.message||'No se pudo guardar.');}finally{delete e.target.dataset.saving;closeButtons.forEach(b=>b.disabled=false);reset();}};}
function patientForm(id){const p=patient(id)||{};modal(id?'Editar paciente':'Nuevo paciente',`<div class="form-grid">${field('Nombre completo','name','text',p.name,true,'maxlength="120"')}${field('Cédula','document','text',p.document)}${field('Fecha de nacimiento','birth','date',p.birth,false,`max="${today()}"`)}${field('Teléfono','phone','tel',p.phone)}${field('Correo electrónico','email','email',p.email)}${field('Dirección','address','text',p.address)}${field('Contacto de emergencia y teléfono','emergency','text',p.emergency)}${selectField('Estado','active',[['true','Activo'],['false','Archivado']],String(p.active??true))}${area('⚠ Alerta médica crítica: alergias, hipertensión, diabetes','alert',p.alert)}${area('Antecedentes y observaciones','notes',p.notes)}</div>`,async f=>{const values=Object.fromEntries(f);values.name=values.name.trim();values.document=values.document.trim();if(!values.name)throw Error('Ingresá el nombre del paciente.');if(values.document&&db.patients.some(x=>x.document===values.document&&x.id!==id))throw Error('Ya existe un paciente con esa cédula.');const next=structuredClone(db);const record={...values,id:id||uid(),active:values.active==='true'};if(id)next.patients[next.patients.findIndex(x=>x.id===id)]=record;else next.patients.push(record);await commit(next);});}
function requirePatients(){if(!db.patients.some(p=>p.active)){toast('Registrá un paciente activo primero.');return false;}return true;}
function deleteButton(kind,id){return button('Eliminar','delete-record',`data-kind="${kind}" data-id="${id}"`,'small danger');}
function deleteRecord(kind,id){
 if(!['treatments','payments'].includes(kind))return;
 const record=db[kind].find(r=>r.id===id);if(!record)return;
 const title=kind==='payments'?'Eliminar pago':'Eliminar procedimiento';
 modal(title,`<p>${esc(record.description)} · ${money(kind==='payments'?record.amount:record.cost)}</p><p>Se recalcularán el saldo pendiente y el crédito del paciente.</p>${kind==='treatments'?'<p>Los pagos y la nota clínica se conservan. Lo que sobre queda a favor del paciente.</p>':''}<label class="check"><input type="checkbox" required> Confirmo que deseo eliminar este registro</label><br>`,async()=>{const next=structuredClone(db);next[kind]=next[kind].filter(r=>r.id!==id);await commit(next);});
 const submit=$('#modal-form [type=submit]');submit.textContent='Eliminar';submit.classList.remove('primary');submit.classList.add('danger');
}
function editRecord(kind,id){
 const record=db[kind]?.find(r=>r.id===id);if(!record)throw Error('Registro no disponible.');
 const r=structuredClone(record);
 let html='';
 if(kind==='appointments')html=patientSelect(r.patientId)+treatmentSelect(r.patientId,r.treatmentId||'')+field('Fecha','date','date',r.date,true)+field('Hora','time','time',r.time,true)+field('Duración (minutos)','duration','number',r.duration,true,'min="5" max="480" step="5"')+field('Motivo','reason','text',r.reason,true)+selectField('Estado','status',['Programada','Confirmada','Atendida','Cancelada'],r.status);
 if(kind==='sessions')html=(db.payments.some(p=>p.sessionId===r.id)?`<p>Tratamiento: ${esc(db.treatments.find(t=>t.id===r.treatmentId)?.description||'Tratamiento anterior')}</p><input type="hidden" name="treatmentId" value="${r.treatmentId||''}">`:treatmentSelect(r.patientId,r.treatmentId||''))+field('Etapa','stage','text',r.stage||'',false,'maxlength="500"')+field('Fecha','date','date',r.date,true)+field('Procedimiento','procedure','text',r.procedure,true)+area('Evolución','notes',r.notes)+field('Anestesia','anesthesia','text',r.anesthesia)+field('Materiales','materials','text',r.materials)+field('Enlace al estudio','url','url',r.url);
 if(kind==='treatments')html=field('Fecha (si se conoce)','date','date',r.date||'')+selectField('Fase','phase',['Fase I','Fase II','Fase III'],r.phase)+field('Pieza FDI','tooth','text',r.tooth)+field('Procedimiento','description','text',r.description,true)+field('Presupuesto (Gs.)','cost','number',r.cost,true,'min="0" max="1000000000" step="1"')+selectField('Estado','status',['Pendiente','En Curso','Completado'],r.status)+`<label class="check"><input type="checkbox" name="longTerm" ${r.longTerm?'checked':''}> Lleva varias sesiones</label><br>`+field('Etapa actual','stage','text',r.stage||'',false,'maxlength="500"')+area('Plan y objetivos','plan',r.plan||'');
 if(kind==='payments')html=patientSelect(r.patientId)+treatmentSelect(r.patientId,r.treatmentId||'')+field('Fecha','date','date',r.date,true)+field('Concepto','description','text',r.description,true)+field('Importe (Gs.)','amount','number',r.amount,true,'min="1" max="1000000000" step="1"')+selectField('Método de pago','method',['Efectivo','Transferencia','Tarjeta'],r.method);
 modal('Editar registro',html,async f=>{
 const updated={...r,...Object.fromEntries(f)};if(kind==='treatments')updated.longTerm=f.has('longTerm');if('treatmentId' in updated&&!updated.treatmentId)delete updated.treatmentId;if(kind==='payments'&&(updated.patientId!==r.patientId||updated.treatmentId!==r.treatmentId))delete updated.sessionId;
 for(const key of ['duration','cost','amount'])if(key in updated)updated[key]=Number(updated[key]);
 if(kind==='sessions'&&updated.url&&new URL(updated.url).protocol!=='https:')throw Error('El enlace debe utilizar HTTPS.');
 if(kind==='appointments'&&updated.status!=='Cancelada'){
 const minutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3));
 if(db.appointments.some(x=>x.id!==id&&x.date===updated.date&&x.status!=='Cancelada'&&minutes(updated.time)<minutes(x.time)+x.duration&&minutes(x.time)<minutes(updated.time)+updated.duration))throw Error('Este horario se superpone con otra cita.');
 }
 if(kind==='treatments'&&!updated.date)delete updated.date;const next=structuredClone(db);next[kind][next[kind].findIndex(x=>x.id===id)]=updated;if(kind==='treatments'&&!r.longTerm&&!updated.longTerm&&sessionsFor(db,id).length===1){const session=next.sessions.find(x=>x.treatmentId===id);if(session.procedure===r.description){if(updated.date)session.date=updated.date;session.procedure=updated.description;}}if(kind==='sessions'&&updated.treatmentId&&sessionsFor(next,updated.treatmentId).length>1)next.treatments.find(t=>t.id===updated.treatmentId).longTerm=true;await commit(next);
 });bindTreatmentPatient();
}
function editButton(kind,id){return button('Editar','edit-record',`data-kind="${kind}" data-id="${id}"`,'small');}
function appointmentForm(treatmentId){const treatment=db.treatments.find(t=>t.id===treatmentId);if(!requirePatients())return;modal('Agendar cita',`<div class="form-grid">${patientSelect(treatment?.patientId||selected||'')}${treatmentSelect(treatment?.patientId||selected||db.patients.find(p=>p.active)?.id,treatment?.id||'')}${field('Fecha','date','date',view==='agenda'&&agendaDay?agendaDay:today(),true)}${field('Hora','time','time','09:00',true)}${field('Duración (minutos)','duration','number',30,true,'min="5" max="480" step="5"')}${field('Motivo','reason','text',treatment?`Control · ${treatment.description}`:'',true)}</div>`,async f=>{const a=Object.fromEntries(f);if(!a.treatmentId)delete a.treatmentId;a.duration=Number(a.duration);const minutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3));if(db.appointments.some(x=>x.date===a.date&&x.status!=='Cancelada'&&minutes(a.time)<minutes(x.time)+x.duration&&minutes(x.time)<minutes(a.time)+a.duration))throw Error('Este horario se superpone con otra cita.');const next=structuredClone(db);next.appointments.push({...a,id:uid(),status:'Programada'});await commit(next);});bindTreatmentPatient();}
function toothForm(n){const t=db.teeth[selected]?.[n]||{};modal(`Pieza ${n} · Estado por cara`,`<p class="muted">Seleccioná el estado de cada cara. Para una pieza ausente, marcá las cinco caras como Ausente.</p><div class="form-grid">${faces.map(f=>selectField(f,f,Object.keys(colors),t[f]||'Sano')).join('')}</div>`,async f=>{const next=structuredClone(db);next.teeth[selected]??={};next.teeth[selected][n]=Object.fromEntries(f);await commit(next);});}
function readFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:reader.result});reader.onerror=reject;reader.readAsDataURL(file);});}
function sessionForm(){modal('Registrar evolución clínica',`${treatmentSelect(selected)}${field('Fecha de la sesión','date','date',today(),true)}${field('Procedimiento realizado','procedure','text','',true)}${area('Evolución y notas clínicas','notes')}${field('Anestesia aplicada','anesthesia')}${field('Materiales utilizados','materials')}${field('Enlace a imagen o estudio (HTTPS)','url','url')}${field('Adjuntar imágenes o PDF (máximo 10 MB en total)','files','file','',false,'multiple accept="image/png,image/jpeg,image/webp,application/pdf"')}`,async f=>{const files=f.getAll('files').filter(x=>x.size);if(files.reduce((s,x)=>s+x.size,0)>10*1024*1024)throw Error('Los adjuntos superan el límite de 10 MB.');if(files.some(x=>!['image/png','image/jpeg','image/webp','application/pdf'].includes(x.type)))throw Error('Usá imágenes PNG, JPEG, WebP o PDF.');const url=f.get('url');if(url&&new URL(url).protocol!=='https:')throw Error('El enlace debe utilizar HTTPS.');const next=structuredClone(db);const record={id:uid(),patientId:selected,date:f.get('date'),procedure:f.get('procedure'),notes:f.get('notes'),anesthesia:f.get('anesthesia'),materials:f.get('materials'),url,files:await Promise.all(files.map(readFile))};if(f.get('treatmentId'))await commit(appendCourseSession(db,f.get('treatmentId'),record));else{next.sessions.push(record);await commit(next);}});}
function treatmentForm(){modal('Nuevo tratamiento',`<div class="form-grid">${field('Tratamiento','description','text','',true,'maxlength="500"')}${field('Total acordado (Gs.)','cost','number',0,true,'min="0" max="1000000000" step="1"')}${field('Fecha de inicio','date','date',today(),true)}${selectField('Estado','status',['Pendiente','En Curso','Completado'])}<label class="check full"><input type="checkbox" id="f-longTerm" name="longTerm"> Lleva varias sesiones (ortodoncia, rehabilitación u otro)</label>${field('Etapa actual (opcional)','stage','text','',false,'maxlength="500"')}${area('Plan y objetivos (opcional)','plan')}</div>`,async f=>{const next=structuredClone(db);next.treatments.push({...Object.fromEntries(f),longTerm:f.has('longTerm'),cost:Number(f.get('cost')),id:uid(),patientId:selected,phase:'Fase I',tooth:''});await commit(next);});$('#f-longTerm').onchange=()=>{if($('#f-longTerm').checked&&$('#f-status').value==='Pendiente')$('#f-status').value='En Curso';};}

function paymentForm(id,treatmentId){const treatment=db.treatments.find(t=>t.id===treatmentId&&t.patientId===id);if(!requirePatients()&&!patient(id))return;modal('Anotar pago',`<div class="form-grid">${treatment?`<p><strong>${esc(pname(id))}</strong></p><input type="hidden" name="patientId" value="${id}">`:patientSelect(id||'')}${!treatment?treatmentSelect(id||db.patients.find(p=>p.active)?.id):''}${field('Fecha','date','date',today(),true)}${field('Tratamiento o motivo','description','text',treatment?.description||'',true)}${field('Pagó (Gs.)','amount','number',treatment?treatmentBalances(db).rows.get(treatment.id).balance:'',true,'min="1" max="1000000000" step="1"')}${selectField('Cómo pagó','method',['Efectivo','Transferencia','Tarjeta'])}</div><p class="muted">${treatment?'El pago se aplica a este tratamiento. Lo que sobra queda a favor del paciente.':'El pago se aplica a los tratamientos del paciente.'}</p>`,async f=>{const next=structuredClone(db);const payment={...Object.fromEntries(f),amount:Number(f.get('amount')),id:uid(),...(treatment?{treatmentId:treatment.id}:{})};if(!payment.treatmentId)delete payment.treatmentId;next.payments.push(payment);await commit(next);});bindTreatmentPatient();}
function login(){
 const setup=needsSetup;
 $('#app').innerHTML=`<main class="login"><section class="card">${brand()}<h1>${setup?'Crear acceso':'Ingresar'}</h1><form id="login-form">${field('Usuario','username','text','karen.frutos',true,'autocomplete="username" autocapitalize="none" spellcheck="false"')}
 <div class="field"><label for="f-password">Contraseña</label><div class="password-input"><input id="f-password" name="password" type="password" required minlength="${setup?12:1}" autocomplete="${setup?'new-password':'current-password'}"><button type="button" class="password-toggle" data-action="toggle-password" aria-controls="f-password" aria-label="Mostrar contraseña" aria-pressed="false">Mostrar</button></div></div>
 ${setup?field('Repetir contraseña','confirm','password','',true,'minlength="12" autocomplete="new-password"')+field('Clave de instalación','token','password','',true,'autocomplete="off"'):''}
 <label class="remember-option" for="f-remember"><input id="f-remember" name="remember" type="checkbox"><span>Mantener sesión iniciada por 30 días</span></label>
 <p class="error" role="alert"></p><button class="btn primary login-submit" type="submit">${setup?'Crear acceso':'Ingresar'}</button></form></section></main>`;
 $('#login-form').onsubmit=async e=>{e.preventDefault();const reset=busy(e.submitter,'Ingresando…');try{const f=new FormData(e.target);if(setup&&f.get('password')!==f.get('confirm'))throw Error('Las contraseñas no coinciden.');const result=await api(setup?'setup':'login',{username:f.get('username'),password:f.get('password'),token:f.get('token'),remember:f.has('remember')});csrf=result.csrf;auth=true;needsSetup=false;await loadClinic();render();}catch(err){if($('#login-form .error'))$('#login-form .error').textContent=err.message;}finally{reset();}};
}
function passwordForm(){modal('Cambiar contraseña',`${field('Contraseña actual','current','password','',true,'autocomplete="current-password"')}${field('Nueva contraseña','password','password','',true,'minlength="12" autocomplete="new-password"')}${field('Repetir nueva contraseña','confirm','password','',true,'minlength="12" autocomplete="new-password"')}`,async f=>{if(f.get('password')!==f.get('confirm'))throw Error('Las contraseñas no coinciden.');await api('password',{current:f.get('current'),password:f.get('password')});});}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function validateBackup(b){if(b?.format!=='vital-dent'||b.version!==1)throw Error('Formato de respaldo no compatible.');const d=b.data;const keys=['patients','appointments','sessions','treatments','payments'];if(!d||keys.some(k=>!Array.isArray(d[k]))||!d.teeth||typeof d.teeth!=='object'||Array.isArray(d.teeth))throw Error('Respaldo incompleto.');for(const k of keys){const ids=new Set();for(const r of d[k]){if(!r||typeof r.id!=='string'||!(/^[a-f0-9-]{36}$/).test(r.id)||ids.has(r.id))throw Error('Registros inválidos o duplicados.');ids.add(r.id);}}
 const str=(r,ks)=>ks.every(k=>typeof r[k]==='string');const day=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s));const ids=new Set(d.patients.map(p=>p.id));
 if(d.patients.some(p=>!str(p,['name','document','phone','email','address','emergency','notes','alert','birth'])||!p.name.trim()||typeof p.active!=='boolean'))throw Error('Pacientes inválidos.');
 for(const k of keys.slice(1))if(d[k].some(r=>!ids.has(r.patientId)||k!=='treatments'&&!day(r.date)))throw Error('Referencias o fechas inválidas.');
 if(d.appointments.some(r=>!str(r,['time','reason'])||!/^([01]\d|2[0-3]):[0-5]\d$/.test(r.time)||!Number.isFinite(r.duration)||r.duration<5||!['Programada','Confirmada','Atendida','Cancelada'].includes(r.status)))throw Error('Citas inválidas.');
 if(d.treatments.some(r=>!str(r,['description','tooth'])||!['Fase I','Fase II','Fase III'].includes(r.phase)||!['Pendiente','En Curso','Completado'].includes(r.status)||!Number.isFinite(r.cost)||r.cost<0))throw Error('Tratamientos inválidos.');
 if(d.payments.some(r=>!str(r,['description'])||!Number.isFinite(r.amount)||r.amount<=0||!['Efectivo','Transferencia','Tarjeta'].includes(r.method)))throw Error('Cobros inválidos.');
 if(d.sessions.some(r=>!str(r,['procedure','notes','anesthesia','materials','url'])||r.url&&!/^https:\/\//i.test(r.url)||!Array.isArray(r.files)||r.files.some(f=>!str(f,['name','type'])||!['image/png','image/jpeg','image/webp','application/pdf'].includes(f.type)||!(typeof f.data==='string'&&f.data.startsWith(`data:${f.type};base64,`)||typeof f.id==='string'&&/^[a-f0-9]{64}$/.test(f.id)))))throw Error('Sesiones o adjuntos inválidos.');
 for(const t of d.treatments)if(t.date!==undefined&&(!day(t.date)||t.date===''))throw Error('Fecha del tratamiento inválida.');
 for(const list of [d.treatments,d.sessions,d.payments,d.appointments])for(const r of list)for(const key of ['treatmentId','appointmentId','sessionId'])if(r[key]!==undefined&&(typeof r[key]!=='string'||!/^[a-f0-9-]{36}$/.test(r[key])))throw Error('Referencia inválida.');
 for(const r of [...d.sessions,...d.payments,...d.appointments]){const t=d.treatments.find(t=>t.id===r.treatmentId);if(t&&t.patientId!==r.patientId)throw Error('El tratamiento pertenece a otro paciente.');const a=d.appointments.find(a=>a.id===r.appointmentId);if(a&&a.patientId!==r.patientId)throw Error('La cita pertenece a otro paciente.');}
 for(const p of d.payments){const s=d.sessions.find(s=>s.id===p.sessionId);if(s&&(s.patientId!==p.patientId||s.treatmentId!==p.treatmentId))throw Error('El pago no corresponde a esta sesión.');}
 for(const t of d.treatments){if(t.longTerm!==undefined&&typeof t.longTerm!=='boolean')throw Error('Tipo de tratamiento inválido.');if(t.plan!==undefined&&(typeof t.plan!=='string'||t.plan.length>50000))throw Error('Plan inválido.');}
 for(const r of [...d.treatments,...d.sessions])if(r.stage!==undefined&&(typeof r.stage!=='string'||r.stage.length>500))throw Error('Etapa inválida.');
 for(const [pid,teeth]of Object.entries(d.teeth)){if(!ids.has(pid)||!teeth||typeof teeth!=='object')throw Error('Odontograma inválido.');for(const [n,t]of Object.entries(teeth)){if(!/^(?:[1-4][1-8]|[5-8][1-5])$/.test(n)||!t||typeof t!=='object'||Object.entries(t).some(([f,s])=>!faces.includes(f)||!Object.hasOwn(colors,s)))throw Error('Caras dentales inválidas.');}}
 return d;}
async function exportBackup(){
 const copy=structuredClone(db);toast('Preparando respaldo con adjuntos…');
 for(const session of copy.sessions)for(const file of session.files){if(!file.data)file.data=(await api(`attachment&id=${encodeURIComponent(file.id)}`)).data;delete file.id;}
 download(JSON.stringify({format:'vital-dent',version:1,exportedAt:new Date().toISOString(),data:copy}),`vital-dent-${today()}.json`,'application/json');
 toast('Respaldo descargado');
}
async function importBackup(){const input=document.createElement('input');input.type='file';input.accept='application/json,.json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('El respaldo supera los 30 MB permitidos en esta versión.');const next=validateBackup(JSON.parse(await file.text()));modal('Restaurar respaldo',`<p>Se reemplazarán los datos actuales por ${next.patients.length} pacientes, ${next.sessions.length} sesiones y ${next.payments.length} cobros. Exportá primero un respaldo actual si necesitás conservarlo.</p><label class="check"><input type="checkbox" required> Confirmo el reemplazo de los datos</label><br>`,async()=>{await commit(next);selected=null;});}catch(e){toast(e.message);}};input.click();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const menu=b.closest('.record-options');if(menu)menu.open=false;if(b.dataset.action==='toggle-password'){const input=$('#f-password');const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Ocultar':'Mostrar';b.setAttribute('aria-label',show?'Ocultar contraseña':'Mostrar contraseña');b.setAttribute('aria-pressed',String(show));return;}if(b.dataset.action==='close'){$('#modal').close();return;}if(b.dataset.nav){view=b.dataset.nav;selected=null;render();return;}if(b.dataset.tab){tab=b.dataset.tab;render();return;}const a=b.dataset.action;if(!a)return;if(a==='delete-record'){if(auth)deleteRecord(b.dataset.kind,b.dataset.id);return;}if(a==='edit-record'){if(auth)editRecord(b.dataset.kind,b.dataset.id);return;}if(!auth&&a!=='close')return;const reset=['logout','refresh','export','attachment','install'].includes(a)?busy(b,a==='export'?'Exportando…':'Un momento…'):()=>{};try{switch(a){case'open-course':{const t=db.treatments.find(t=>t.id===b.dataset.id);if(t){courseId=t.id;selected=t.patientId;courseTab=b.dataset.panel||'sessions';courseLimit=12;view='course';render();}break;}case'back-to-patient':view='patient';tab='plans';render();break;case'course-session':courseSessionForm(b.dataset.id);break;case'course-tab':courseTab=b.dataset.value;render();break;case'course-more':courseLimit+=12;render();break;case'attention-form':attentionForm(b.dataset.id,b.dataset.appointment);break;case'payment-history':paymentHistory(b.dataset.id,b.dataset.treatment);break;case'home-more':homeLimit+=15;$('#home-records').innerHTML=homeRecords();break;case'home-citas':homeCitas=b.dataset.value;render();break;case'calendar-day':agendaDay=b.dataset.date;render();break;case'calendar-today':agendaDay=today();agendaMonth=agendaDay.slice(0,7);render();break;case'calendar-month':{const [y,m]=agendaMonth.split('-').map(Number);agendaMonth=localDate(new Date(y,m-1+Number(b.dataset.step),1)).slice(0,7);render();break;}case'logout':await api('logout',{});auth=false;db=emptyDB();view='dashboard';selected=null;$('#modal').replaceChildren();await boot();break;case'refresh':await loadClinic();render();toast('Datos actualizados');break;case'go-patients':view='patients';selected=null;render();break;case'open-patient':sessionFilter='';selected=b.dataset.id;view='patient';tab='info';render();break;case'patient-form':patientForm(b.dataset.id);break;case'appointment-form':appointmentForm(b.dataset.treatment);break;case'dentition':dentition=b.dataset.value;render();break;case'tooth':toothForm(b.dataset.id);break;case'session-form':sessionForm();break;case'treatment-form':treatmentForm();break;case'payment-form':paymentForm(b.dataset.id,b.dataset.treatment);break;case'password':passwordForm();break;case'export':await exportBackup();break;case'import':await importBackup();break;case'attachment':{const f=db.sessions.find(s=>s.id===b.dataset.id)?.files[Number(b.dataset.index)];if(f){const source=f.data||(await api(`attachment&id=${encodeURIComponent(f.id)}`)).data;const blob=await(await fetch(source)).blob();download(blob,f.name,f.type);}break;}case'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('iPhone: Safari → Compartir → Agregar a pantalla de inicio. PC: menú del navegador → Instalar aplicación.');break;}}catch(err){toast(err.message);}finally{reset();}});
document.addEventListener('input',e=>{if(e.target.id==='home-search'){homeQuery=e.target.value;homeLimit=15;$('#home-records').innerHTML=homeRecords();}if(e.target.id==='patient-search'){const q=e.target.value.toLocaleLowerCase().trim();$('#patient-results').innerHTML=patientRows(db.patients.filter(p=>[p.name,p.document,p.phone].some(v=>v.toLocaleLowerCase().includes(q))));}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='f-sessionFilter'){sessionFilter=el.value;render();}if(el.id==='home-filter'){homeFilter=el.value;homeLimit=15;$('#home-records').innerHTML=homeRecords();}if(el.id==='agenda-date'){agendaDay=el.value;if(agendaDay)agendaMonth=agendaDay.slice(0,7);render();}if(el.id==='cash-date')$('#cash-results').innerHTML=paymentTable(db.payments.filter(p=>!el.value||p.date===el.value));if(el.dataset.treatment||el.dataset.appointment){try{const next=structuredClone(db);const list=el.dataset.treatment?next.treatments:next.appointments;list.find(x=>x.id===(el.dataset.treatment||el.dataset.appointment)).status=el.value;await commit(next);if(['agenda','course','patient'].includes(view))render();toast('Estado actualizado');}catch(err){toast(err.message);render();}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
for(const event of ['online','offline'])window.addEventListener(event,()=>{const el=$('#online');if(el){el.textContent=navigator.onLine?'● En línea':'● Sin conexión';el.className=`badge ${navigator.onLine?'green':''}`;}});
function connectionError(error){
 const fields=['server_version','expected_origin','received_origin','referer_origin','fetch_site'];
 const diagnostic={client_version:APP_VERSION,opened_origin:location.origin,http_status:error.status||0,error_code:error.code||'connection_error'};
 for(const field of fields){const value=error.diagnostic?.[field];if(typeof value==='string')diagnostic[field]=value.slice(0,250);}
 let canonical='';
 try{const url=new URL(diagnostic.expected_origin);if(['http:','https:'].includes(url.protocol)&&!url.username&&!url.password&&url.origin!==location.origin)canonical=url.origin+'/';}catch{}
 $('#app').innerHTML=`<main class="login"><section class="card connection-error"><h1>${error.code==='origin_not_allowed'?'Acceso bloqueado por dominio':'No se pudo conectar al servidor'}</h1><p>${esc(error.message)}</p>${canonical?`<a class="btn primary" href="${esc(canonical)}">Abrir dirección autorizada</a>`:''}<div class="actions"><button type="button" class="btn ${canonical?'':'primary'}" id="retry-connection">Reintentar</button><button type="button" class="btn" id="copy-diagnostic">Copiar diagnóstico</button></div><details id="diagnostic-details"><summary>Ver diagnóstico</summary><label for="connection-diagnostic" class="sr-only">Diagnóstico de conexión</label><textarea id="connection-diagnostic" readonly spellcheck="false"></textarea></details></section></main>`;
 const text=JSON.stringify(diagnostic,null,2);$('#connection-diagnostic').value=text;
 $('#retry-connection').onclick=boot;
 $('#copy-diagnostic').onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('Diagnóstico copiado');}catch{$('#diagnostic-details').open=true;$('#connection-diagnostic').focus();$('#connection-diagnostic').select();toast('Copiá el texto seleccionado');}};
}
async function boot(){
 try{const status=await api('status');csrf=status.csrf;auth=status.authenticated;needsSetup=status.setup;db=emptyDB();if(auth)await loadClinic();render();}
 catch(e){connectionError(e);}
}
const canonical=canonicalUrl(location.href);
if(canonical){location.replace(canonical);}else{
 if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
 await boot();
}

document.addEventListener('click',e=>{for(const menu of document.querySelectorAll('.record-options[open]'))if(!menu.contains(e.target))menu.open=false;});
document.addEventListener('keydown',e=>{if(e.key==='Escape')for(const menu of document.querySelectorAll('.record-options[open]'))menu.open=false;});
